    if (k === "sp") { box.dataset.sp = el.dataset.id; box.querySelectorAll(".sps button").forEach(b => b.classList.toggle("sel", b === el)); box.querySelector(".ab").classList.toggle("on", el.dataset.id === "ab"); const t = { one: "오늘 하루에 필요한 말을 한 장으로 보는 거란다.", ppf: "지나온 길, 지금, 앞으로의 흐름을 차례로 보는 거란다.", adv: "고민이 뭔지, 뭐가 막는지, 어떻게 하면 좋을지 보는 거란다.", love: "네 마음과 그 사람 마음, 둘의 흐름을 보는 거란다.", ab: "두 길을 놓고 각각 어떻게 될지 비교해 보는 거란다. A와 B를 적어 주렴.", cc: quota().sup || (opt.isAdmin && opt.isAdmin()) ? "켈틱 크로스는 100년 넘게 쓰인 10장 펼치기란다. 지금·막는 것·마음 깊은 곳·결과까지 한 번에 본단다." : "켈틱 크로스는 10장으로 깊게 보는 점이란다. 오늘 💛 응원해 준 손님에게 고마움으로 봐 준단다." }[el.dataset.id]; const go = box.querySelector(".go[data-do=start]"); if (go) go.classList.toggle("off", el.dataset.id === "cc" && !quota().sup && !(opt.isAdmin && opt.isAdmin())); return typeSay(t); }
    if (k === "start") return startShuffle();
